const rank = card => card % 13;
function nextSeat(hands, seat) {
  for (let offset = 1; offset <= hands.length; offset++) {
    const next = (seat + offset) % hands.length;
    if (hands[next].length) return next;
  }
  return seat;
}
const game = {
  newMatch(ctx) {
    const deck = Array.from({length:52}, (_, i) => i);
    let seed = 2166136261;
    for (const player of ctx.players) {
      for (const letter of player.id) seed = Math.imul(seed ^ letter.charCodeAt(0), 16777619);
    }
    for (let i=deck.length-1;i>0;i--) {
      seed=(Math.imul(seed,1664525)+1013904223)>>>0;
      const j=seed%(i+1);
      [deck[i],deck[j]]=[deck[j],deck[i]];
    }
    const hands=ctx.players.map((_,i)=>deck.filter((_,j)=>j%ctx.players.length===i));
    return {state:{hands,pile:[],seat:0,flips:0,winners:[]},turn:[ctx.players[0].id]};
  },
  applyMove(s,id,move,ctx) {
    const match=s.pile.length>=2&&rank(s.pile[s.pile.length-1])===rank(s.pile[s.pile.length-2]);
    if (!move || Object.keys(move).length!==1 || s.winners.length || s.flips>=160 ||
        ctx.players[s.seat].id!==id || !["flip","snap"].includes(move.action) ||
        (move.action==="snap"&&!match)) throw new InvalidMove("Choose a legal move on your turn.");
    const hands=s.hands.map(hand=>[...hand]);
    let pile=[...s.pile],flips=s.flips;
    if(move.action==="snap"){
      hands[s.seat].push(...pile);
      pile=[];
    }else{
      pile.push(hands[s.seat].shift());
      flips++;
    }
    const live=hands.filter(hand=>hand.length).length;
    const terminal=live===1||flips===160;
    const high=Math.max(...hands.map(hand=>hand.length));
    const winners=terminal?hands.flatMap((hand,i)=>hand.length===high?[i]:[]):[];
    const seat=nextSeat(hands,s.seat);
    const state={hands,pile,seat,flips,winners};
    if(!terminal)return {state,turn:[ctx.players[seat].id]};
    const humans=ctx.players.filter(player=>player.kind==="human"&&player.active!==false);
    const winning=humans.filter(player=>winners.includes(ctx.players.indexOf(player)));
    const paid=winning.length?winning:humans;
    return {state,turn:null,payouts:Object.fromEntries(paid.map((player,i)=>[player.id,
      Math.floor(ctx.pot/paid.length)+(i<ctx.pot%paid.length?1:0)]))};
  },
  viewFor(s){
    return {counts:s.hands.map(hand=>hand.length),top:s.pile.slice(-2),pileCount:s.pile.length,
      seat:s.seat,flips:s.flips,winners:s.winners};
  },
  computerMove(s){
    return {action:s.pile.length>=2&&rank(s.pile[s.pile.length-1])===rank(s.pile[s.pile.length-2])?"snap":"flip"};
  },
  randomMove(s){return this.computerMove(s);}
};

